  /** Fail startup with one categorized dependency error so the shared recovery surface owns presentation. */
  function requireDependency(value, label) {
    if (value) return value;
    throw new NeonDependencyError(`${label} dependency missing`, {
      code: 'dependency-unavailable'
    });
  }

  requireDependency(
    typeof startup.markRuntimeReady === 'function'
      && typeof startup.isUpdateNoticeActive === 'function'
      && typeof startup.registerUpdateContinueHandler === 'function',
    'Neon update notice boundary'
  );
  const i18n = requireDependency(window.NeonI18n, 'Neon i18n module');
