        code: options.code || error?.code,
        title: options.title || uiText('error.runtimeTitle'),
        message: options.message || uiText('error.runtimeMessage'),
        ...(typeof options.filename === 'string' && options.filename
          ? { filename: options.filename }
          : {}),
        ...(Number.isFinite(options.line) ? { line: options.line } : {}),
        ...(Number.isFinite(options.column) ? { column: options.column } : {})
