      clusterCount: geometry.userData.skyTerrainClusterCount,
      minimumEmptySpaceRatio: geometry.userData.skyTerrainMinimumEmptySpaceRatio,
      authoredEmptySpaceRatio: geometry.userData.skyTerrainAuthoredEmptySpaceRatio,
