  const terrainChunkPosition = new THREE.Vector3();
  const terrainChunkQuaternion = new THREE.Quaternion();
  const terrainChunkScale = new THREE.Vector3(1, 1, 1);
  const terrainChunkYAxis = new THREE.Vector3(0, 1, 0);
  const terrainChunkColor = new THREE.Color();
