  let terrainResidencyVerticalSlope = 0;
  let terrainResidencyHorizontalSlope = 0;
  let terrainOriginTravelM = 0;
  let terrainRelativeMotionM = 0;
  let terrainRelativeMotionErrorM = 0;
  let terrainWorldAnchorErrorM = 0;
  let terrainProceduralWorldOriginX = 0;
  let terrainProceduralWorldOriginZ = 0;
